# Generated by Cursor
"""Unit tests for quote scan (space rule, start=open, apostrophe iff, canonical)."""

from scripts.rule_normalizations.quote_scan import scan_turn_quotes


def _tuples(text: str, path: str = "test") -> list[tuple[str, int, str]]:
    """Return (rule_id, start_index, span) for each result (drop path_str)."""
    return [(r, s, sp) for r, s, sp, _ in scan_turn_quotes(text, path)]


def test_space_rule_open_then_close() -> None:
    """Space before first quote -> open; space after second -> close."""
    out = _tuples('" word "')
    assert len(out) == 2
    assert out[0] == ("open_double_quote", 0, '"')
    assert out[1] == ("close_double_quote", 7, '"')


def test_word_at_end_close() -> None:
    """Quote before space/end -> close."""
    out = _tuples('word"')
    assert len(out) == 1
    assert out[0] == ("close_double_quote", 4, '"')


def test_start_of_turn_open() -> None:
    r"""Start of string = space before; \"word at start -> open."""
    out = _tuples('"word')
    assert len(out) == 1
    assert out[0] == ("open_double_quote", 0, '"')


def test_apostrophe_start_paired_open() -> None:
    """'I object." -> apostrophe open, straight quote close (unopened close directly after)."""
    out = _tuples("to say, 'I object.\" All")
    assert len(out) == 2
    assert out[0][0] == "open_double_quote" and out[0][2] == "'"
    assert out[1][0] == "close_double_quote" and out[1][2] == '"'


def test_apostrophe_start_no_close_after_not_open() -> None:
    """'tis fine -> no unopened close directly after, so apostrophe not open."""
    out = _tuples("'tis fine")
    # Apostrophe at start of word with no close quote after -> not open (iff fails)
    assert not any(r == "open_double_quote" and sp == "'" for r, _, sp in out)


def test_apostrophe_end_with_unclosed_open_close() -> None:
    """Jones' with unclosed open before and no close directly after -> apostrophe can be close."""
    out = _tuples("The \"quote Jones' end")
    # Open at ", then apostrophe at end of Jones' with no " directly after -> close
    assert len(out) == 2
    assert out[0] == ("open_double_quote", 4, '"')
    assert out[1][0] == "close_double_quote" and out[1][2] == "'"


def test_apostrophe_end_close_directly_after_not_close() -> None:
    """Word' " -> apostrophe not close (unopened close directly after)."""
    out = _tuples("word' \"")
    # Apostrophe at end of word; next quote is " (close). So apostrophe is NOT close per iff.
    # We should get only the " as close (or both but apostrophe not classified as close)
    [(r, s, sp) for r, s, sp in out if r == "open_double_quote"]
    closes = [(r, s, sp) for r, s, sp in out if r == "close_double_quote"]
    assert not any(sp == "'" for _, _, sp in closes)
    assert len(closes) >= 1  # at least the "


def test_canonical_open() -> None:
    """‶ labor -> open (canonical left char)."""
    out = _tuples("\u2036 labor")  # ‶
    assert len(out) == 1
    assert out[0] == ("open_double_quote", 0, "\u2036")


def test_canonical_close() -> None:
    """procedure." -> close."""
    out = _tuples('procedure."')
    assert len(out) == 1
    assert out[0] == ("close_double_quote", 10, '"')


def test_curly_single_quotes_emit_open_close() -> None:
    """Curly single quotes U+2018 (open) and U+2019 (close) emit open/close_double_quote."""
    # Edited by Cursor
    text = "\u2018I object.\u2019"  # 'I object.'
    out = _tuples(text)
    assert len(out) == 2
    assert out[0][0] == "open_double_quote" and out[0][2] == "\u2018"
    assert out[1][0] == "close_double_quote" and out[1][2] == "\u2019"
